use vstd::prelude::*;

verus! {

spec fn flipud_seq(s: Seq<f32>) -> Seq<f32> {
    Seq::new(s.len(), |i: int| s[s.len() - 1 - i])
}

fn flipud(m: Vec<f32>) -> (result: Vec<f32>)
    ensures
        result@ == flipud_seq(m@),
{
    let n = m.len();
    let mut result = Vec::with_capacity(n);

    for i in 0..n
        invariant
            n == m.len(),
            result@.len() == i,
            forall|j: int|
                0 <= j < i ==> result@[j] == m@[n as int - 1 - j],
    {
        result.push(m[n - 1 - i]);
    }

    result
}

} // verus!

